create table public.learning_catalog (
  id text primary key check (id ~ '^[a-z0-9][a-z0-9-]{0,63}$'),
  definition jsonb not null check (jsonb_typeof(definition) = 'object' and definition->>'id' = id and octet_length(definition::text) <= 200000),
  readings jsonb not null check (jsonb_typeof(readings) = 'object' and octet_length(readings::text) <= 500000),
  questions jsonb not null check (jsonb_typeof(questions) = 'array' and jsonb_array_length(questions) = 3),
  created_at timestamptz not null default now()
);
create table public.learning_answer_keys (
  path_id text primary key references public.learning_catalog(id) on delete restrict,
  questions jsonb not null check (jsonb_typeof(questions) = 'array' and jsonb_array_length(questions) = 3)
);
create table public.learning_goals (
  user_id uuid primary key references auth.users(id) on delete cascade,
  skills text[] not null default '{}' check (cardinality(skills) <= 20),
  minutes_per_day integer not null default 30 check (minutes_per_day between 10 and 180),
  version integer not null default 1 check (version > 0)
);
create index skillpath_enrollments_by_path on public.skillpath_enrollments(path_id);
alter table public.learning_catalog enable row level security;
alter table public.learning_answer_keys enable row level security;
alter table public.learning_goals enable row level security;
revoke all on public.learning_catalog, public.learning_answer_keys, public.learning_goals from public, anon, authenticated;
grant select on public.learning_catalog, public.learning_goals to authenticated;
grant select, insert, update, delete on public.learning_catalog, public.learning_answer_keys, public.learning_goals to service_role;
create policy "Signed-in catalogue reading" on public.learning_catalog for select to authenticated using (true);
create policy "Own learning goals" on public.learning_goals for select to authenticated using ((select auth.uid()) = user_id);

-- Existing progress and certificates refer to stable content. Publish a new ID to revise an enrolled course.
create function public.protect_enrolled_learning_content() returns trigger
language plpgsql set search_path = public as $$
begin
  if exists (select 1 from public.skillpath_enrollments where path_id = coalesce(to_jsonb(old)->>'path_id', to_jsonb(old)->>'id')) then
    raise exception 'Enrolled content is immutable; publish a new course ID';
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;
revoke all on function public.protect_enrolled_learning_content() from public, anon, authenticated;
create trigger protect_learning_catalog before update or delete on public.learning_catalog for each row execute function public.protect_enrolled_learning_content();
create trigger protect_learning_answer_keys before update or delete on public.learning_answer_keys for each row execute function public.protect_enrolled_learning_content();
insert into public.learning_catalog (id, definition, readings, questions) values ('web-foundations', $seed${"id":"web-foundations","title":"Build your first accessible website","description":"Turn a design into a responsive, keyboard-friendly page.","skills":["HTML","CSS","Accessibility"],"roles":["frontend","web","ui"],"level":"Beginner","prerequisites":"A browser and a free local editor; no prior coding required.","lessons":[{"id":"html","title":"Structure content with HTML","provider":"MDN","url":"https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Structuring_content","minutes":60,"task":"Create a job-detail page with semantic headings, a list and a labelled form.","alternative":"https://developer.mozilla.org/en-US/docs/Learn_web_development","format":"reading","embedUrl":null,"verifiedOn":"2026-09-17","access":"Free public learning. No certificate is issued for this individual resource. Optional provider upgrades are not required."},{"id":"html-video","title":"HTML Full Course — optional video route","provider":"freeCodeCamp.org","url":"https://www.youtube.com/watch?v=pQN-pnXPaVg","minutes":120,"task":"Apply the HTML concepts to your own job-detail page. Older video: use current MDN for reference.","alternative":"https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Structuring_content","format":"video","embedUrl":"https://www.youtube-nocookie.com/embed/pQN-pnXPaVg","verifiedOn":"2026-09-17","access":"Free public learning. No certificate is issued for this individual resource. Optional provider upgrades are not required."},{"id":"layout","title":"Responsive CSS layout","provider":"MDN","url":"https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/CSS_layout","minutes":90,"task":"Make your page work at 390px and desktop widths without horizontal scrolling.","alternative":"https://developer.mozilla.org/en-US/docs/Learn_web_development","format":"reading","embedUrl":null,"verifiedOn":"2026-09-17","access":"Free public learning. No certificate is issued for this individual resource. Optional provider upgrades are not required."},{"id":"accessibility","title":"Accessible interactions","provider":"web.dev","url":"https://web.dev/learn/accessibility","minutes":90,"task":"Use the form with keyboard only; check labels, focus and error messages.","alternative":"https://developer.mozilla.org/en-US/docs/Learn_web_development","format":"reading","embedUrl":null,"verifiedOn":"2026-09-17","access":"Free public learning. No certificate is issued for this individual resource. Optional provider upgrades are not required."}],"project":"Build a fictional job-opportunity page with responsive layout and an accessible enquiry form. Document keyboard checks and three design decisions. No paid hosting required.","credential":{"title":"Explore a full freeCodeCamp certification","issuer":"freeCodeCamp","url":"https://www.freecodecamp.org/learn/","requirements":"Separate provider account and the complete relevant provider curriculum/projects are required. This shorter JobPilot path does not earn a freeCodeCamp certificate."}}$seed$::jsonb, $seed${"html":{"outcome":"Choose semantic elements and connect a visible label to an input.","explanation":["HTML describes the meaning of content. A heading introduces a topic, a list groups related items and a button performs an action. Choosing the right element gives browsers and assistive technology useful information before any CSS is applied.","Start your fictional job page with one main topic. Use links for navigation and buttons for actions. A form input needs a visible label; a placeholder disappears while typing and is not a substitute for that label."],"example":"<main>\n  <h1>Frontend opportunity</h1>\n  <ul><li>Remote collaboration</li></ul>\n  <label for=\"question\">Your question</label>\n  <input id=\"question\" name=\"question\">\n  <button type=\"button\">Save draft</button>\n</main>","walkthrough":"The label's for value matches the input id. The button is already keyboard-operable. Its type prevents an accidental form submission when used inside a form.","mistake":"Replacing a button with a clickable div creates extra keyboard and accessibility work.","reflection":"Should a control that opens a job-detail URL be a link or a button?","answer":"A link: it navigates to a destination. Use a button for an action such as saving a draft."},"html-video":{"outcome":"Turn a visual job card into meaningful HTML without copying a tutorial project.","explanation":["Treat a video as one explanation route, not a requirement to imitate its output. Identify the content in your own design: a title, employer, location and destination. Then choose elements based on their meaning.","Use the in-app reading route if video playback is unavailable. Build the same exercise either way. Test the result before adding styling: the heading and link should still make sense as plain text."],"example":"<article>\n  <h2>Interface developer</h2>\n  <p>Example Studio · Jaipur</p>\n  <a href=\"/opportunities/interface\">Read opportunity</a>\n</article>","walkthrough":"The article is a self-contained card. The heading names the opportunity, and the link communicates its destination without relying on colour.","mistake":"A whole card with nested clickable controls can create confusing interaction targets.","reflection":"What should still work if your CSS does not load?","answer":"The content order, headings, labels and navigation should remain understandable and usable."},"layout":{"outcome":"Build a flexible layout that does not overflow a narrow screen.","explanation":["Responsive design is about available space, not a list of device brands. Begin with one column. Add columns when the content has enough room, and let text wrap instead of forcing a fixed width.","Grid and flex children may need min-width: 0 to shrink below their content width. Long URLs and code are common overflow sources. Give code its own scrolling container rather than making the entire page scroll sideways."],"example":".cards { display: grid; gap: 1rem; }\n.card { min-width: 0; overflow-wrap: anywhere; }\n@media (min-width: 48rem) {\n  .cards { grid-template-columns: repeat(2, minmax(0, 1fr)); }\n}","walkthrough":"The default layout works without a media query. At wider sizes two equal columns appear; minmax(0, 1fr) allows each column to shrink.","mistake":"A fixed 900px child can overflow even when its parent is responsive.","reflection":"What should you check besides a 390px screenshot?","answer":"Try longer content, keyboard focus, increased text size and browser zoom. A screenshot alone does not prove usability."},"accessibility":{"outcome":"Make a form usable with a keyboard and understandable error feedback.","explanation":["Accessibility is part of the interaction design. A user should find controls in a sensible tab order, see where focus is, understand each field and recover from errors without guessing.","Describe an error next to its field and connect that message using aria-describedby. Do not communicate failure through colour alone. Only set aria-invalid when a field is actually invalid."],"example":"<label for=\"email\">Email</label>\n<input id=\"email\" type=\"email\" aria-invalid=\"true\"\n  aria-describedby=\"email-error\">\n<p id=\"email-error\">Enter a valid email address.</p>","walkthrough":"This example represents an already invalid field. In a real form, update the state after validation and preserve what the user typed.","mistake":"Removing outlines without providing an equally visible focus style hides keyboard position.","reflection":"How do you check a save action without using a mouse?","answer":"Tab to it, verify visible focus, activate it with the keyboard and check that success or failure is communicated."}}$seed$::jsonb, $seed$[{"prompt":"A clickable action should normally use which HTML element?","options":["A styled div","A button","A heading"]},{"prompt":"What is the useful first check for a narrow-screen layout?","options":["Check for overflow at a narrow viewport","Hide all text","Disable browser zoom"]},{"prompt":"How should an input's purpose be communicated?","options":["Only with colour","Only with placeholder text","With an associated visible label"]}]$seed$::jsonb);
insert into public.learning_answer_keys (path_id, questions) values ('web-foundations', $seed$[{"prompt":"A clickable action should normally use which HTML element?","options":["A styled div","A button","A heading"],"correct":1,"explanation":"A native button supplies keyboard and interaction semantics."},{"prompt":"What is the useful first check for a narrow-screen layout?","options":["Check for overflow at a narrow viewport","Hide all text","Disable browser zoom"],"correct":0,"explanation":"Content should remain readable without horizontal overflow or blocking zoom."},{"prompt":"How should an input's purpose be communicated?","options":["Only with colour","Only with placeholder text","With an associated visible label"],"correct":2,"explanation":"A persistent associated label supports comprehension and accessible naming."}]$seed$::jsonb);
insert into public.learning_catalog (id, definition, readings, questions) values ('javascript-typescript', $seed${"id":"javascript-typescript","title":"JavaScript into reliable TypeScript","description":"Model data, handle asynchronous work and guard unknown inputs.","skills":["JavaScript","TypeScript"],"roles":["frontend","full stack","web"],"level":"Intermediate","prerequisites":"Basic HTML and familiarity with variables/functions.","lessons":[{"id":"javascript","title":"JavaScript foundations","provider":"MDN","url":"https://developer.mozilla.org/en-US/docs/Web/JavaScript/Guide","minutes":120,"task":"Write a function that filters a list of jobs by location; handle an empty list.","alternative":"https://www.youtube.com/watch?v=PkZNo7MFNFg","format":"reading","embedUrl":null,"verifiedOn":"2026-09-17","access":"Free public learning. No certificate is issued for this individual resource. Optional provider upgrades are not required."},{"id":"javascript-video","title":"Learn JavaScript — optional video route","provider":"freeCodeCamp.org","url":"https://www.youtube.com/watch?v=PkZNo7MFNFg","minutes":210,"task":"Implement your own search/filter exercise, rather than copying the instructor project. Older video: cross-check current MDN.","alternative":"https://developer.mozilla.org/en-US/docs/Web/JavaScript/Guide","format":"video","embedUrl":"https://www.youtube-nocookie.com/embed/PkZNo7MFNFg","verifiedOn":"2026-09-17","access":"Free public learning. No certificate is issued for this individual resource. Optional provider upgrades are not required."},{"id":"promises","title":"Promises and failure states","provider":"MDN","url":"https://developer.mozilla.org/en-US/docs/Web/JavaScript/Guide/Using_promises","minutes":60,"task":"Load a local JSON file and display loading, success and failure states.","alternative":"https://developer.mozilla.org/en-US/docs/Web/JavaScript/Guide","format":"reading","embedUrl":null,"verifiedOn":"2026-09-17","access":"Free public learning. No certificate is issued for this individual resource. Optional provider upgrades are not required."},{"id":"types","title":"Everyday types and narrowing","provider":"TypeScript","url":"https://www.typescriptlang.org/docs/handbook/2/narrowing.html","minutes":90,"task":"Validate unknown job data before reading it; avoid unsafe casts.","alternative":"https://www.typescriptlang.org/docs/handbook/2/everyday-types.html","format":"reading","embedUrl":null,"verifiedOn":"2026-09-17","access":"Free public learning. No certificate is issued for this individual resource. Optional provider upgrades are not required."}],"project":"Build a typed job-list filter using local sample data. Add checks for missing fields, duplicate IDs and failed loading; describe your validation boundary.","credential":null}$seed$::jsonb, $seed${"javascript":{"outcome":"Filter fictional data without modifying the source array.","explanation":["A small function should make its inputs and output obvious. Filtering returns a new array containing items that match a condition, while the original collection stays available for another view.","Normalize the search input once and decide what an empty search means. Test an empty list and a search with no matches. These are normal product states, not exceptional failures."],"example":"function filterJobs(jobs, location) {\n  const query = location.trim().toLowerCase();\n  return jobs.filter(job =>\n    job.location.toLowerCase().includes(query));\n}\nfilterJobs([], \"Jaipur\"); // []","walkthrough":"This function assumes job.location has already been validated as a string. An empty query matches every location; that is an explicit design choice.","mistake":"Assuming API fields are always present moves input validation problems into rendering.","reflection":"Does filter change the original array?","answer":"No. It returns a new array, although the objects inside it still refer to the original objects."},"javascript-video":{"outcome":"Translate a JavaScript concept into your own search interaction.","explanation":["Use functions to separate the data operation from the interface. A search function should not need a DOM node; it can take an array and query and return an answer you can test.","The video is an optional supplement. For the exercise, invent your own fictional data and write down the behaviour before coding: trim spaces, ignore case and preserve the original list."],"example":"const jobs = [{ title: \"React developer\" }, { title: \"SQL analyst\" }];\nconst query = \" react \".trim().toLowerCase();\nconst matches = jobs.filter(job =>\n  job.title.toLowerCase().includes(query));\nconsole.log(matches.length); // 1","walkthrough":"Normalization makes spaces and capitalization less surprising. The same matching function can support a web screen or a local test.","mistake":"Copying a tutorial's finished interface without understanding its data flow makes changes difficult.","reflection":"Name two useful cases for this function's test.","answer":"An empty query and a query with no matches. Also check mixed-case text and that the original list is unchanged."},"promises":{"outcome":"Represent loading, success and failure as different outcomes.","explanation":["A promise represents work whose result arrives later. Await makes the sequence readable, but the operation can still fail. A useful interface explains whether it is waiting, finished or needs a retry.","Fetch rejects for some network failures but not simply because a server returned an error status. Check response.ok before parsing data. Validate the parsed value before treating it as application data."],"example":"async function loadJobs() {\n  const response = await fetch(\"/sample-jobs.json\");\n  if (!response.ok) throw new Error(\"Could not load jobs\");\n  const data = await response.json();\n  if (!Array.isArray(data)) throw new Error(\"Invalid list\");\n  return data;\n}","walkthrough":"The array check is only the first validation step; each row still needs field validation. Callers should catch failures and offer a retry rather than leave a permanent spinner.","mistake":"Clearing an existing draft when a request fails causes avoidable data loss.","reflection":"Is a 404 response guaranteed to reject fetch?","answer":"No. Fetch can resolve with a non-success HTTP status; inspect response.ok or response.status."},"types":{"outcome":"Narrow unknown input before reading its fields.","explanation":["TypeScript helps check the code you write, but it does not make a remote payload trustworthy at runtime. Treat incoming data as unknown until checks establish the fields you need.","Narrowing refines the type through a condition. Prefer a real property check over an assertion that merely tells the compiler to trust you. Keep that validation at the input boundary."],"example":"function readTitle(value: unknown): string | null {\n  if (typeof value !== \"object\" || value === null) return null;\n  if (!(\"title\" in value) || typeof value.title !== \"string\") return null;\n  return value.title.trim() || null;\n}","walkthrough":"The null check matters because typeof null is object. The property and string checks establish what can safely be read.","mistake":"Casting JSON with as Job does not validate it.","reflection":"What runtime guarantee does a TypeScript assertion provide?","answer":"None. It changes the compiler's interpretation, not the value received at runtime."}}$seed$::jsonb, $seed$[{"prompt":"What should you do with unknown external data?","options":["Cast it and trust it","Validate before reading its fields","Ignore failure cases"]},{"prompt":"Which promise outcome needs a recoverable UI state?","options":["Only success","Only pending","Rejection as well as success and pending"]},{"prompt":"What does narrowing a union type achieve?","options":["Proves which operations are valid in that branch","Encrypts the value","Makes network requests synchronous"]}]$seed$::jsonb);
insert into public.learning_answer_keys (path_id, questions) values ('javascript-typescript', $seed$[{"prompt":"What should you do with unknown external data?","options":["Cast it and trust it","Validate before reading its fields","Ignore failure cases"],"correct":1,"explanation":"Type assertions do not perform runtime validation."},{"prompt":"Which promise outcome needs a recoverable UI state?","options":["Only success","Only pending","Rejection as well as success and pending"],"correct":2,"explanation":"Users need useful loading and error recovery, not just the happy path."},{"prompt":"What does narrowing a union type achieve?","options":["Proves which operations are valid in that branch","Encrypts the value","Makes network requests synchronous"],"correct":0,"explanation":"A guard narrows the possibilities and allows safe type-specific operations."}]$seed$::jsonb);
insert into public.learning_catalog (id, definition, readings, questions) values ('react-workflows', $seed${"id":"react-workflows","title":"React workflows users can trust","description":"Create predictable state, forms and recoverable asynchronous screens.","skills":["React","JavaScript"],"roles":["react","frontend","full stack"],"level":"Intermediate","prerequisites":"JavaScript functions, arrays and basic HTML.","lessons":[{"id":"react","title":"React Quick Start","provider":"React","url":"https://react.dev/learn","minutes":90,"task":"Split a learning dashboard into small components with explicit props.","alternative":"https://react.dev/learn/thinking-in-react","format":"reading","embedUrl":null,"verifiedOn":"2026-09-17","access":"Free public learning. No certificate is issued for this individual resource. Optional provider upgrades are not required."},{"id":"state","title":"Manage state deliberately","provider":"React","url":"https://react.dev/learn/managing-state","minutes":90,"task":"Keep a lesson selection and derive its title; avoid duplicate state.","alternative":"https://react.dev/learn/thinking-in-react","format":"reading","embedUrl":null,"verifiedOn":"2026-09-17","access":"Free public learning. No certificate is issued for this individual resource. Optional provider upgrades are not required."},{"id":"effects","title":"Synchronize only external systems","provider":"React","url":"https://react.dev/learn/synchronizing-with-effects","minutes":60,"task":"Fetch sample data with cleanup and a retry button; calculate derived values during rendering.","alternative":"https://react.dev/learn","format":"reading","embedUrl":null,"verifiedOn":"2026-09-17","access":"Free public learning. No certificate is issued for this individual resource. Optional provider upgrades are not required."},{"id":"react-video","title":"React beginner video — concepts supplement (2022)","provider":"freeCodeCamp.org","url":"https://www.youtube.com/watch?v=bMknfKXIFA8","minutes":180,"task":"Practise component/state concepts. Skip outdated Create React App setup and follow current React documentation.","alternative":"https://react.dev/learn","format":"video","embedUrl":"https://www.youtube-nocookie.com/embed/bMknfKXIFA8","verifiedOn":"2026-09-17","access":"Free public learning. No certificate is issued for this individual resource. Optional provider upgrades are not required."}],"project":"Build a local application tracker with editable notes, a confirmation step and loading/error/empty states. Include keyboard checks and explain how you prevent state drift.","credential":{"title":"Explore a full freeCodeCamp certification","issuer":"freeCodeCamp","url":"https://www.freecodecamp.org/learn/","requirements":"Separate provider account and the complete relevant provider curriculum/projects are required. This shorter JobPilot path does not earn a freeCodeCamp certificate."}}$seed$::jsonb, $seed${"react":{"outcome":"Give a component a small, explicit input contract.","explanation":["A React component describes the interface for its current inputs. Begin with a small boundary such as a lesson card; pass only the information and actions it actually needs.","Keep stable identifiers in list keys. When data changes order, a title or array index may not describe the identity of the item. An explicit id helps React preserve the correct component state."],"example":"function LessonCard({ title, onOpen }) {\n  return <article>\n    <h2>{title}</h2>\n    <button type=\"button\" onClick={onOpen}>Continue</button>\n  </article>;\n}","walkthrough":"The parent owns navigation or selection. The card receives an action rather than independently inventing another source of selected-lesson state.","mistake":"Defining component functions inside another component can reset their identity on every render.","reflection":"Should this card fetch the whole profile to display a title?","answer":"No. Pass the title and required action; fetch shared data at an appropriate existing boundary."},"state":{"outcome":"Store the selection once and derive its displayed information.","explanation":["State should represent information that changes independently. If a selected title can be found from the selected id and the lesson list, storing both creates two values that can disagree.","Use state updates that preserve the previous value when the next result depends on it. Do not mutate an existing array or object and expect React to infer a reliable change."],"example":"const [selectedId, setSelectedId] = useState(lessons[0].id);\nconst selected = lessons.find(lesson => lesson.id === selectedId);\nconst [bookmarks, setBookmarks] = useState([]);\nfunction bookmark(id) {\n  setBookmarks(current => current.includes(id) ? current : [...current, id]);\n}","walkthrough":"The title comes from selected, so a title edit in the lesson list appears without synchronizing duplicate state. Bookmark updates use the latest state.","mistake":"Using an effect to keep two derived state values synchronized adds unnecessary failure paths.","reflection":"What should you store: selectedId or selectedTitle plus selectedId?","answer":"Usually just selectedId; derive the title from the current lesson data."},"effects":{"outcome":"Clean up an external synchronization when its component goes away.","explanation":["Effects connect a component to something outside rendering, such as a network request or event subscription. Calculating a filtered list is not an external synchronization and can happen during rendering.","When a request becomes irrelevant, cleanup should cancel or ignore its result. Otherwise an older response can update a screen that has moved to another selection."],"example":"useEffect(() => {\n  const controller = new AbortController();\n  fetch(\"/sample.json\", { signal: controller.signal })\n    .then(response => {\n      if (!response.ok) throw new Error(\"Load failed\");\n      return response.json();\n    }).then(setData).catch(error => {\n      if (error.name !== \"AbortError\") setError(\"Please retry\");\n    });\n  return () => controller.abort();\n}, []);","walkthrough":"Cleanup aborts the request. The UI still needs a loading state, payload validation and a retry interaction; this excerpt only demonstrates lifecycle cleanup.","mistake":"Adding an effect for every computed value obscures the real synchronization boundaries.","reflection":"Does filtering an already-loaded array need an effect?","answer":"No. Derive it from the current inputs during rendering."},"react-video":{"outcome":"Apply component and state concepts without adopting outdated tooling.","explanation":["Older tutorials can still explain stable concepts such as props and state, but their installation instructions may no longer be appropriate. Separate the concept from the version-specific setup.","Build your own tiny application tracker: select an item by id and edit a draft note. Show the saved value separately from pending changes so users understand what survives refresh."],"example":"const [draft, setDraft] = useState(\"\");\nconst [saved, setSaved] = useState(\"\");\nconst dirty = draft !== saved;\n// A real app awaits a successful server save before updating saved.\n<button disabled={!dirty} onClick={() => setSaved(draft)}>\n  Save local demo\n</button>","walkthrough":"This local demo is not persistence. In a real app, a failed save must retain the draft and keep the saved value unchanged.","mistake":"Treating a disabled save button or local state as proof that the server stored the changes.","reflection":"When should a real app show Saved?","answer":"After the server confirms the write, not merely after clicking the button."}}$seed$::jsonb, $seed$[{"prompt":"A title can be calculated from a selected lesson ID. Where should it usually come from?","options":["A second independently updated state variable","A calculation from the current selection","A timer"]},{"prompt":"Which task is an effect suitable for?","options":["Calculating a total from props","Formatting a label","Synchronizing an external subscription with cleanup"]},{"prompt":"When switching between independently reviewed applications, what must happen?","options":["Reset the review confirmation for the new application","Reuse the previous confirmation","Hide the application title"]}]$seed$::jsonb);
insert into public.learning_answer_keys (path_id, questions) values ('react-workflows', $seed$[{"prompt":"A title can be calculated from a selected lesson ID. Where should it usually come from?","options":["A second independently updated state variable","A calculation from the current selection","A timer"],"correct":1,"explanation":"Deriving values avoids redundant state drifting out of sync."},{"prompt":"Which task is an effect suitable for?","options":["Calculating a total from props","Formatting a label","Synchronizing an external subscription with cleanup"],"correct":2,"explanation":"Effects synchronize external systems; rendering calculations usually do not need them."},{"prompt":"When switching between independently reviewed applications, what must happen?","options":["Reset the review confirmation for the new application","Reuse the previous confirmation","Hide the application title"],"correct":0,"explanation":"Approval belongs to the reviewed item and must not leak to another item."}]$seed$::jsonb);
insert into public.learning_catalog (id, definition, readings, questions) values ('backend-apis', $seed${"id":"backend-apis","title":"Build safe backend APIs","description":"Understand HTTP, asynchronous execution and testable server boundaries.","skills":["Node.js","API","Testing"],"roles":["backend","full stack","node"],"level":"Intermediate","prerequisites":"JavaScript functions and promises; a free local Node.js installation.","lessons":[{"id":"node","title":"Introduction to Node.js","provider":"Node.js","url":"https://nodejs.org/en/learn/getting-started/introduction-to-nodejs","minutes":60,"task":"Create a local server returning a fictional course catalogue.","alternative":"https://nodejs.org/en/learn/asynchronous-work/overview-of-blocking-vs-non-blocking","format":"reading","embedUrl":null,"verifiedOn":"2026-09-17","access":"Free public learning. No certificate is issued for this individual resource. Optional provider upgrades are not required."},{"id":"http","title":"HTTP request/response fundamentals","provider":"MDN","url":"https://developer.mozilla.org/en-US/docs/Web/HTTP/Guides/Overview","minutes":60,"task":"Write down response codes for unauthenticated access, invalid input and missing data.","alternative":"https://nodejs.org/en/learn/getting-started/introduction-to-nodejs","format":"reading","embedUrl":null,"verifiedOn":"2026-09-17","access":"Free public learning. No certificate is issued for this individual resource. Optional provider upgrades are not required."},{"id":"async","title":"Blocking versus non-blocking work","provider":"Node.js","url":"https://nodejs.org/en/learn/asynchronous-work/overview-of-blocking-vs-non-blocking","minutes":60,"task":"Compare sequential and independent concurrent operations without blocking the server.","alternative":"https://nodejs.org/en/learn/getting-started/introduction-to-nodejs","format":"reading","embedUrl":null,"verifiedOn":"2026-09-17","access":"Free public learning. No certificate is issued for this individual resource. Optional provider upgrades are not required."},{"id":"tests","title":"The built-in test runner","provider":"Node.js","url":"https://nodejs.org/en/learn/test-runner/introduction","minutes":90,"task":"Test validation and an unauthorized request using the built-in runner.","alternative":"https://developer.mozilla.org/en-US/docs/Web/HTTP/Guides/Overview","format":"reading","embedUrl":null,"verifiedOn":"2026-09-17","access":"Free public learning. No certificate is issued for this individual resource. Optional provider upgrades are not required."}],"project":"Build a local-only sample learning API with input validation, fictional users and ownership checks. Include runnable happy-path and denial checks. Do not use real personal data.","credential":null}$seed$::jsonb, $seed${"node":{"outcome":"Return a small JSON response from a local-only Node server.","explanation":["Node runs JavaScript outside the browser. A server receives requests and returns responses; keep a local learning server separate from production accounts and use fictional data.","A response has a status, headers and a body. Set the content type so a client knows how to interpret the body, and listen on the loopback interface for a local-only exercise."],"example":"import { createServer } from \"node:http\";\ncreateServer((request, response) => {\n  response.writeHead(200, { \"Content-Type\": \"application/json\" });\n  response.end(JSON.stringify([{ id: \"intro\", title: \"First lesson\" }]));\n}).listen(3001, \"127.0.0.1\");","walkthrough":"The example always returns the same catalogue. A real route must check the method, path, authentication and inputs before returning protected data.","mistake":"Binding an experimental server publicly when the exercise only needs local access.","reflection":"Does returning JSON automatically enforce ownership?","answer":"No. Authentication and row ownership are separate checks that must be implemented at the boundary."},"http":{"outcome":"Choose response statuses that explain what happened.","explanation":["HTTP communicates more than a success message. A caller needs to distinguish missing authentication, denied access, malformed input, missing data and a conflict with newer saved data.","Choose a status and a bounded, understandable error message. Avoid exposing database details or confirming the existence of another user's private record."],"example":"Missing authentication: 401\nForbidden operation: 403\nInvalid input: 400\nNot found or not owned: 404\nStale version conflict: 409\nTemporarily unavailable: 503","walkthrough":"An ownership-safe 404 can intentionally avoid disclosing whether a foreign private row exists. A 409 can tell a client to preserve edits and reload the saved version.","mistake":"Returning 200 for failed writes makes clients mistake a failure for saved progress.","reflection":"Which response helps protect an unsaved draft from a stale tab overwrite?","answer":"A version check with a 409 conflict; the client should retain the draft instead of overwriting newer data."},"async":{"outcome":"Run independent asynchronous work together without losing dependency order.","explanation":["Asynchronous I/O lets other work proceed while a request waits. It does not make CPU-heavy JavaScript magically parallel. Long synchronous work can still block the event loop.","Use concurrency when operations are independent. If one needs another's result, preserve that sequence. Concurrency also needs a bound when processing a large collection."],"example":"const [catalogue, preferences] = await Promise.all([\n  loadCatalogue(),\n  loadPreferences()\n]);\n// If profileId is needed, obtain it first:\nconst profileId = await readProfileId();\nconst progress = await loadProgress(profileId);","walkthrough":"The first two operations start together. The progress request starts only after its required id is known. Promise.all rejects if any member rejects.","mistake":"Starting thousands of requests at once can overload your own server or the provider.","reflection":"Can Promise.all speed up two operations when the second needs the first result?","answer":"Not directly. Respect the dependency; only independent branches can start together."},"tests":{"outcome":"Leave a runnable check for a real input-validation branch.","explanation":["A useful test fails when important behaviour breaks. Begin with one happy path and one denial or invalid-input case rather than scaffolding a large suite with no meaningful assertions.","Node includes a test runner and strict assertions. Use small fictional inputs. A mocked database can test route logic, but it does not prove the actual database access policies."],"example":"import test from \"node:test\";\nimport assert from \"node:assert/strict\";\nconst validTitle = value => typeof value === \"string\" && value.trim().length > 0;\ntest(\"requires a non-empty title\", () => {\n  assert.equal(validTitle(\"Intro\"), true);\n  assert.equal(validTitle(\"  \"), false);\n  assert.equal(validTitle(null), false);\n});\n// Run a saved .mjs file with: node --test filename.mjs","walkthrough":"The test covers the successful value, whitespace and a wrong type. Add real role/ownership database checks separately when protecting stored user data.","mistake":"Only asserting that a function returned something does not verify its security decision.","reflection":"Does a mocked owner filter prove production RLS works?","answer":"No. Run the corresponding allow/deny checks against the real database roles and policies."}}$seed$::jsonb, $seed$[{"prompt":"What should an API check before changing private user data?","options":["Only the requested record ID","Authentication and ownership","Only the button label"]},{"prompt":"What does a TypeScript type do to an incoming JSON body at runtime?","options":["Nothing; validation is still required","Automatically rejects invalid data","Automatically authenticates the request"]},{"prompt":"Which is safe for independent asynchronous reads?","options":["Busy-waiting","Blocking the event loop","Concurrent promises with failure handling"]}]$seed$::jsonb);
insert into public.learning_answer_keys (path_id, questions) values ('backend-apis', $seed$[{"prompt":"What should an API check before changing private user data?","options":["Only the requested record ID","Authentication and ownership","Only the button label"],"correct":1,"explanation":"An authenticated user still must be authorized for the specific row."},{"prompt":"What does a TypeScript type do to an incoming JSON body at runtime?","options":["Nothing; validation is still required","Automatically rejects invalid data","Automatically authenticates the request"],"correct":0,"explanation":"Static types do not validate incoming untrusted data."},{"prompt":"Which is safe for independent asynchronous reads?","options":["Busy-waiting","Blocking the event loop","Concurrent promises with failure handling"],"correct":2,"explanation":"Independent asynchronous work can run concurrently without blocking execution."}]$seed$::jsonb);
insert into public.learning_catalog (id, definition, readings, questions) values ('sql-data', $seed${"id":"sql-data","title":"SQL for useful product questions","description":"Query, join and summarize relational data without losing its meaning.","skills":["SQL","PostgreSQL"],"roles":["backend","data","analyst","full stack"],"level":"Beginner","prerequisites":"A free local PostgreSQL installation or a paper-based query exercise.","lessons":[{"id":"select","title":"Query a table","provider":"PostgreSQL","url":"https://www.postgresql.org/docs/current/tutorial-select.html","minutes":60,"task":"Query fictional courses by subject and explain the ordering.","alternative":"https://www.postgresql.org/docs/current/tutorial.html","format":"reading","embedUrl":null,"verifiedOn":"2026-09-17","access":"Free public learning. No certificate is issued for this individual resource. Optional provider upgrades are not required."},{"id":"joins","title":"Join related tables","provider":"PostgreSQL","url":"https://www.postgresql.org/docs/current/tutorial-join.html","minutes":60,"task":"Find enrolled learners, including those without an assessment attempt.","alternative":"https://www.postgresql.org/docs/current/tutorial.html","format":"reading","embedUrl":null,"verifiedOn":"2026-09-17","access":"Free public learning. No certificate is issued for this individual resource. Optional provider upgrades are not required."},{"id":"aggregate","title":"Aggregate without misleading counts","provider":"PostgreSQL","url":"https://www.postgresql.org/docs/current/tutorial-agg.html","minutes":60,"task":"Count completed lessons per learner and explain GROUP BY versus WHERE.","alternative":"https://www.postgresql.org/docs/current/tutorial.html","format":"reading","embedUrl":null,"verifiedOn":"2026-09-17","access":"Free public learning. No certificate is issued for this individual resource. Optional provider upgrades are not required."},{"id":"sql-video","title":"CS50 SQL lecture","provider":"CS50","url":"https://cs50.harvard.edu/x/weeks/7/","minutes":120,"task":"Design three product questions and answer them with your own queries.","alternative":"https://www.postgresql.org/docs/current/tutorial.html","format":"video","embedUrl":null,"verifiedOn":"2026-09-17","access":"Free lecture. Provider assignments/credential require a separate account. Open on CS50; content is not rehosted."}],"project":"Create a fictional course/enrolment/attempt schema and five useful reporting queries. Include a learner with zero attempts and explain how joins affect counts.","credential":null}$seed$::jsonb, $seed${"select":{"outcome":"Select explicit columns and order the result intentionally.","explanation":["A query answers a question about a table. Name the columns you need, filter rows with WHERE and choose an order. Without ORDER BY, do not rely on the database returning rows in a stable sequence.","A small limit is useful for a preview, but it does not explain what the rows mean. Include a stable tie-breaker when values can be equal."],"example":"SELECT id, title\nFROM courses\nWHERE subject = 'web'\nORDER BY title, id\nLIMIT 10;","walkthrough":"The query returns at most ten web courses, sorted by title and then id. It is an illustrative query for a fictional schema, not one to run against JobPilot production.","mistake":"SELECT * can expose unnecessary columns and make consumers depend on accidental schema details.","reflection":"Is a table's apparent insertion order a reliable result order?","answer":"No. State the intended order explicitly with ORDER BY."},"joins":{"outcome":"Keep learners with no attempts in an enrolment report.","explanation":["A join matches related rows. An inner join keeps matching pairs; a left join also keeps each left-side row that has no match, with null values for the missing right side.","A condition on the right-hand table placed in WHERE can remove those null rows. Put match requirements in ON when the report must preserve left-side enrolments without matching attempts."],"example":"SELECT e.learner_id, COUNT(a.id) AS attempts\nFROM enrolments e\nLEFT JOIN attempts a\n  ON a.learner_id = e.learner_id AND a.course_id = e.course_id\nGROUP BY e.learner_id;","walkthrough":"COUNT(a.id) ignores null, so a learner with no matching attempts can have zero. COUNT(*) would count the preserved join row instead.","mistake":"Joining only by learner id mixes attempts from unrelated courses.","reflection":"Why is COUNT(a.id) useful after a left join?","answer":"It counts real non-null attempt ids rather than the synthetic row representing no match."},"aggregate":{"outcome":"Separate row filtering from group filtering.","explanation":["An aggregate summarizes rows, and GROUP BY defines what one output row represents. Decide that meaning first: per learner, per course or per day. Mixing these levels makes counts misleading.","WHERE filters input rows before grouping. HAVING filters the resulting groups. When joins duplicate rows, check whether you need a different join or a distinct count rather than hiding the problem."],"example":"SELECT learner_id, COUNT(*) AS completed\nFROM lesson_progress\nWHERE completed = true\nGROUP BY learner_id\nHAVING COUNT(*) >= 3;","walkthrough":"This assumes one progress row per learner/lesson. Learners with no completed rows are absent; a separate learner table and left join is needed to include them.","mistake":"Presenting only learners with completions as if the report covered every learner.","reflection":"Where should a condition on the final completion count go?","answer":"HAVING, because the aggregate count exists at the group level."},"sql-video":{"outcome":"Design a product question before writing its query.","explanation":["Start with the question: which learners need to retry? Define whether that means their latest attempt failed, every attempt failed or their best score is below a threshold. These are different queries.","This original reading route is an alternative to the external CS50 lecture, not a reproduction of it. Work with fictional data and state the assumptions behind your report."],"example":"SELECT learner_id, MAX(score) AS best_score\nFROM attempts\nGROUP BY learner_id\nHAVING MAX(score) < 67;","walkthrough":"The query identifies learners whose best recorded score is below 67. It excludes learners with no attempts and says nothing about the latest attempt.","mistake":"Confusing best score with latest score changes the product decision.","reflection":"Does this query include a learner who never attempted the check?","answer":"No. Start from enrolments and left join attempts if the report must include that learner."}}$seed$::jsonb, $seed$[{"prompt":"Which join can retain a learner who has no attempt?","options":["INNER JOIN","LEFT JOIN from learners","CROSS JOIN"]},{"prompt":"What does GROUP BY help express?","options":["One summary per chosen grouping","Deleting duplicate tables","Authorization by itself"]},{"prompt":"Can a browser-supplied user ID alone authorize a private SQL update?","options":["Yes","Only if it is a UUID","No; enforce authenticated ownership"]}]$seed$::jsonb);
insert into public.learning_answer_keys (path_id, questions) values ('sql-data', $seed$[{"prompt":"Which join can retain a learner who has no attempt?","options":["INNER JOIN","LEFT JOIN from learners","CROSS JOIN"],"correct":1,"explanation":"A left join retains rows from the left side, even without a match."},{"prompt":"What does GROUP BY help express?","options":["One summary per chosen grouping","Deleting duplicate tables","Authorization by itself"],"correct":0,"explanation":"Grouping supports aggregates such as attempts per learner."},{"prompt":"Can a browser-supplied user ID alone authorize a private SQL update?","options":["Yes","Only if it is a UUID","No; enforce authenticated ownership"],"correct":2,"explanation":"A valid-looking identifier is not proof of permission."}]$seed$::jsonb);
insert into public.learning_catalog (id, definition, readings, questions) values ('git-quality', $seed${"id":"git-quality","title":"Ship collaboratively and accessibly","description":"Use small commits, reviewable branches and practical accessibility checks.","skills":["Git","Accessibility","Testing"],"roles":["software","frontend","web","full stack"],"level":"Beginner","prerequisites":"An existing small local project and a free Git installation.","lessons":[{"id":"git","title":"Pro Git foundations","provider":"Git","url":"https://git-scm.com/book/en/v2","minutes":60,"task":"Initialize a fictional project and explain the working tree, staging area and repository.","alternative":"https://git-scm.com/book/en/v2/Git-Basics-Recording-Changes-to-the-Repository","format":"reading","embedUrl":null,"verifiedOn":"2026-09-17","access":"Free public learning. No certificate is issued for this individual resource. Optional provider upgrades are not required."},{"id":"commits","title":"Record intentional changes","provider":"Git","url":"https://git-scm.com/book/en/v2/Git-Basics-Recording-Changes-to-the-Repository","minutes":45,"task":"Make two focused commits and review their diffs before committing.","alternative":"https://git-scm.com/book/en/v2","format":"reading","embedUrl":null,"verifiedOn":"2026-09-17","access":"Free public learning. No certificate is issued for this individual resource. Optional provider upgrades are not required."},{"id":"branches","title":"Branch and merge safely","provider":"Git","url":"https://git-scm.com/book/en/v2/Git-Branching-Basic-Branching-and-Merging","minutes":60,"task":"Resolve a conflict in a throwaway local repository; preserve both intended changes.","alternative":"https://git-scm.com/book/en/v2","format":"reading","embedUrl":null,"verifiedOn":"2026-09-17","access":"Free public learning. No certificate is issued for this individual resource. Optional provider upgrades are not required."},{"id":"quality","title":"Accessibility as a quality check","provider":"web.dev","url":"https://web.dev/learn/accessibility","minutes":90,"task":"Write a keyboard/focus checklist and fix one real issue in your project.","alternative":"https://developer.mozilla.org/en-US/docs/Learn_web_development","format":"reading","embedUrl":null,"verifiedOn":"2026-09-17","access":"Free public learning. No certificate is issued for this individual resource. Optional provider upgrades are not required."}],"project":"Submit a small repository with a clear README, focused history and an accessibility checklist. Explain one review improvement and one deliberately deferred limitation.","credential":null}$seed$::jsonb, $seed${"git":{"outcome":"Explain the working tree, staging area and committed snapshot.","explanation":["The working tree contains the files you are editing. The staging area selects changes for the next commit. A commit records a snapshot you can refer to and review later.","Inspect status and diffs before recording changes. Use a throwaway local repository for learning commands, and never add real secrets or personal documents to it."],"example":"git init\ngit status --short\ngit add README.md\ngit diff --cached\ngit commit -m \"Describe the sample project\"","walkthrough":"Only the named file is staged. The cached diff shows the content about to be committed, not merely every current working-tree change.","mistake":"Staging everything without reviewing it can include unrelated changes or secrets.","reflection":"Does changing a file after staging automatically update its staged content?","answer":"No. Review and stage the new change explicitly before committing it."},"commits":{"outcome":"Record focused changes another person can review.","explanation":["A focused commit tells one coherent story. It is easier to review and easier to diagnose than a mixture of a feature, unrelated formatting and personal configuration.","Review both staged and unstaged diffs. A commit message should explain the intended change, while the diff shows how it was implemented. Run the smallest relevant validation before committing."],"example":"git diff\ngit add src/filter.js\ngit diff --cached\ngit commit -m \"Handle empty job search results\"\ngit status --short","walkthrough":"The final status reveals changes that were not included. Do not discard another person's changes just to produce a clean working tree.","mistake":"A clean status is not proof that the code works; validation is still required.","reflection":"Should an unrelated colour adjustment join a search-validation fix?","answer":"Usually not. Keep the fix focused unless the change is necessary for the same behaviour."},"branches":{"outcome":"Resolve a local conflict while preserving both intended changes.","explanation":["A branch gives a name to a line of development. A merge combines histories, but Git cannot always decide how overlapping edits should fit together.","When a conflict appears, read both intentions. Edit the final content deliberately, remove conflict markers, review the diff and run the relevant check. Practise only in a disposable local repository."],"example":"git switch -c practice/labels\n# Make and commit a small change in this sample repository.\ngit switch main\ngit merge practice/labels\n# If needed: edit conflicts, review, test, then stage resolved files.","walkthrough":"A clean merge may finish automatically. A conflicted merge needs a deliberate resolution; do not blindly choose one side for every file.","mistake":"Resetting or overwriting the working tree to escape a conflict can destroy uncommitted work.","reflection":"What is the goal of a conflict resolution?","answer":"A final result that preserves the intended behaviour, not merely removal of Git's conflict markers."},"quality":{"outcome":"Create a repeatable keyboard and error-recovery checklist.","explanation":["A quality check should describe an observable behaviour. For a save form, check labels, focus order, keyboard activation, validation messages and whether a failed save preserves the draft.","A checklist complements tests; it does not replace them. Keep it small enough to run before a meaningful change, and document limitations instead of claiming complete accessibility coverage."],"example":"1. Reach each control with Tab.\n2. See a clear focus indicator.\n3. Activate the save action with the keyboard.\n4. Read an understandable error message.\n5. Confirm a failed save keeps the draft.\n6. Retry and confirm the saved value after refresh.","walkthrough":"The last step checks persistence, not just a temporary success message. Test long text and a narrow viewport as well.","mistake":"Testing only the successful mouse-click flow misses users who navigate or recover differently.","reflection":"Is an automated accessibility score a complete accessibility audit?","answer":"No. Automated tools catch some issues; keyboard, content and assistive-technology checks remain important."}}$seed$::jsonb, $seed$[{"prompt":"What should you inspect before making a focused commit?","options":["Only the filename","The staged diff","Only the last commit message"]},{"prompt":"A merge conflict should be resolved by doing what?","options":["Understanding and preserving intended changes","Always deleting both sides","Always choosing the newest line"]},{"prompt":"What is a useful accessibility check?","options":["Disable focus outlines","Check only with a mouse","Navigate and operate controls with the keyboard"]}]$seed$::jsonb);
insert into public.learning_answer_keys (path_id, questions) values ('git-quality', $seed$[{"prompt":"What should you inspect before making a focused commit?","options":["Only the filename","The staged diff","Only the last commit message"],"correct":1,"explanation":"The staged diff reveals the exact changes you are about to record."},{"prompt":"A merge conflict should be resolved by doing what?","options":["Understanding and preserving intended changes","Always deleting both sides","Always choosing the newest line"],"correct":0,"explanation":"A conflict is a semantic decision, not merely a timestamp comparison."},{"prompt":"What is a useful accessibility check?","options":["Disable focus outlines","Check only with a mouse","Navigate and operate controls with the keyboard"],"correct":2,"explanation":"Keyboard checks reveal focus and interaction problems that mouse-only testing misses."}]$seed$::jsonb);
insert into public.learning_catalog (id, definition, readings, questions) values ('computer-science', $seed${"id":"computer-science","title":"Explore computer science with CS50","description":"A short orientation across problem solving, Python, SQL and the web—not the full CS50 course.","skills":["Python","SQL","HTML"],"roles":["software","python","data","web"],"level":"Beginner","prerequisites":"A browser. Completing the external CS50 credential requires its full coursework.","lessons":[{"id":"scratch","title":"Problem-solving foundations","provider":"CS50","url":"https://cs50.harvard.edu/x/weeks/0/","minutes":120,"task":"Describe inputs, outputs and an algorithm for organizing a fictional job shortlist.","alternative":"https://developer.mozilla.org/en-US/docs/Learn_web_development","format":"video","embedUrl":null,"verifiedOn":"2026-09-17","access":"Free lecture. Provider assignments/credential require a separate account. Open on CS50; content is not rehosted."},{"id":"python","title":"Python orientation","provider":"CS50","url":"https://cs50.harvard.edu/x/weeks/6/","minutes":120,"task":"Write a small local script that groups fictional opportunities by location.","alternative":"https://docs.python.org/3/tutorial/","format":"video","embedUrl":null,"verifiedOn":"2026-09-17","access":"Free lecture. Provider assignments/credential require a separate account. Open on CS50; content is not rehosted."},{"id":"sql","title":"SQL orientation","provider":"CS50","url":"https://cs50.harvard.edu/x/weeks/7/","minutes":120,"task":"Compare a table-based approach with your script; describe one useful query.","alternative":"https://www.postgresql.org/docs/current/tutorial.html","format":"video","embedUrl":null,"verifiedOn":"2026-09-17","access":"Free lecture. Provider assignments/credential require a separate account. Open on CS50; content is not rehosted."},{"id":"web","title":"Web orientation","provider":"CS50","url":"https://cs50.harvard.edu/x/weeks/8/","minutes":120,"task":"Present your fictional shortlist as a semantic web page.","alternative":"https://developer.mozilla.org/en-US/docs/Learn_web_development","format":"video","embedUrl":null,"verifiedOn":"2026-09-17","access":"Free lecture. Provider assignments/credential require a separate account. Open on CS50; content is not rehosted."}],"project":"Build a small fictional opportunity organiser. Document the algorithm, data representation and an edge case. Use local tools; no paid cloud services.","credential":{"title":"Free CS50 Certificate","issuer":"CS50","url":"https://cs50.harvard.edu/x/certificate/","requirements":"Requires the full CS50 course, qualifying coursework and final project on the provider. Completing this orientation does not earn it. Choose the free CS50 certificate, not paid edX verification."}}$seed$::jsonb, $seed${"scratch":{"outcome":"Describe an algorithm through inputs, steps and outputs.","explanation":["An algorithm is a precise sequence for solving a problem. Before choosing a language, write down the input, the desired output and the decisions in between.","For a fictional shortlist, decide what to do with duplicate opportunities and missing locations. A deterministic rule makes the result explainable and gives you concrete test cases."],"example":"Input: a list of fictional opportunities\n1. Keep the first occurrence of each id.\n2. Separate rows with a missing location for review.\n3. Group the remaining rows by location.\nOutput: grouped rows plus the review list","walkthrough":"The first-occurrence rule is a choice, not a universal truth. Document it so another person can predict the output.","mistake":"Saying sort the jobs without defining the sort key leaves the algorithm ambiguous.","reflection":"What should this algorithm return for an empty input?","answer":"Empty groups and an empty review list, without inventing an opportunity or failing unexpectedly."},"python":{"outcome":"Group fictional opportunities using a dictionary and a loop.","explanation":["A dictionary maps keys to values. A list holds ordered items. Combine them when each location should map to the opportunities recorded there.","Begin with already validated fictional inputs. Decide how to represent a missing location rather than silently discarding a row. Keep personal information out of learning examples."],"example":"jobs = [{\"title\": \"UI role\", \"location\": \"Jaipur\"}]\ngroups = {}\nfor job in jobs:\n    location = job.get(\"location\") or \"Needs review\"\n    groups.setdefault(location, []).append(job)\nprint(groups)","walkthrough":"setdefault creates the list only when the key is absent, then append adds the current job to that group. This example does not deduplicate ids.","mistake":"Using one shared list for all dictionary keys mixes the groups.","reflection":"Does grouping automatically remove duplicate opportunities?","answer":"No. Add an explicit identity rule if deduplication is required."},"sql":{"outcome":"Compare a relational query with an in-memory grouping operation.","explanation":["A script can group objects already loaded into memory. A relational query asks the database to select and summarize stored rows. Both need clear assumptions about missing values and duplicates.","Choose the representation for the product question. A course with many enrolments is a relationship, not a reason to copy the course title into every user record without considering consistency."],"example":"SELECT location, COUNT(*) AS opportunities\nFROM fictional_jobs\nGROUP BY location\nORDER BY opportunities DESC, location;","walkthrough":"This query counts rows, not unique employers or unique ids. Null locations form their own group unless you explicitly choose another representation.","mistake":"A count with no definition of what one row represents can sound more precise than it is.","reflection":"What does COUNT(*) measure here?","answer":"The number of rows per location. It is not automatically the number of unique employers or valid opportunities."},"web":{"outcome":"Present your organiser with meaningful structure and clear controls.","explanation":["A useful interface makes its data and actions understandable. Present a group heading, a list of opportunities and a clear way to inspect each item. Do not make a count substitute for the content itself.","The browser renders HTML and CSS; JavaScript can update interactions. Begin with a readable static page and add interaction only where it helps the user's actual task."],"example":"<section aria-labelledby=\"jaipur-title\">\n  <h2 id=\"jaipur-title\">Jaipur opportunities</h2>\n  <ul><li><a href=\"/sample/ui\">UI role</a></li></ul>\n</section>","walkthrough":"The heading names the section and the link names its destination. The result remains meaningful without a scripted interaction.","mistake":"Adding a framework before defining the content and user action increases work without clarifying the product.","reflection":"What should your organiser explain about uncertain data?","answer":"Show missing or uncertain fields honestly and provide a review route rather than presenting guessed facts as confirmed."}}$seed$::jsonb, $seed$[{"prompt":"What should an algorithm description make clear?","options":["Only its font","Inputs, operations and expected outputs","Only a certificate name"]},{"prompt":"When grouping data, which is an important edge case?","options":["Only the longest title","Only the happy path","An empty collection or missing grouping value"]},{"prompt":"Does this short orientation earn a CS50 provider certificate?","options":["No; complete the provider's full requirements","Yes, after opening one video","Yes, if a screenshot is uploaded"]}]$seed$::jsonb);
insert into public.learning_answer_keys (path_id, questions) values ('computer-science', $seed$[{"prompt":"What should an algorithm description make clear?","options":["Only its font","Inputs, operations and expected outputs","Only a certificate name"],"correct":1,"explanation":"An algorithm transforms defined inputs through clear steps into outputs."},{"prompt":"When grouping data, which is an important edge case?","options":["Only the longest title","Only the happy path","An empty collection or missing grouping value"],"correct":2,"explanation":"Empty and incomplete data must be handled intentionally."},{"prompt":"Does this short orientation earn a CS50 provider certificate?","options":["No; complete the provider's full requirements","Yes, after opening one video","Yes, if a screenshot is uploaded"],"correct":0,"explanation":"Provider credentials are issued only by that provider under its requirements."}]$seed$::jsonb);
